,occur_date -- 発生日時
,ord_no
from
  mni_monitor
where
  ord_no = @ordNo
 and data_type = 1 and is_del = ''0'' ) a
inner join
  b on a.ord_no = b.ordnob
  and case
        when b.rst_start_date is not null and b.rst_end_date is not null then date_trunc(''minute'',a.occur_date) between date_trunc(''minute'',b.rst_start_date) and date_trunc(''minute'',b.rst_end_date)
        when b.rst_start_date is not null then date_trunc(''minute'',a.occur_date) >= date_trunc(''minute'',b.rst_start_date)
        else false
