INSERT INTO ntss.sys_data_set
(sql_cd, "sql", db_class, detail, can_repeat, use_application, report_class, memo, reg_date, up_date, pre_sql_info)
VALUES(260, 'WITH otc as (
  select
    * 
  from
    ord_treat_condition 
  where
    ord_no = @ordNo
    and facility_cd = @facilityCd
    and is_del = ''0'' 
    and is_disp = ''1''
  order by
    receive_date desc
)
select
  receive_date
  ,treat_class
  ,treat_condition ->> ''0'' as tc_0 -- 患者コード
  ,treat_condition ->> ''14'' as tc_14 -- 透析時間
  ,treat_condition ->> ''15'' as tc_15 -- 治療モード
  ,treat_condition ->> ''16'' as tc_16 -- ＥＣＵＭ選択
  ,treat_condition ->> ''17'' as tc_17 -- ＥＣＵＭ量
  ,treat_condition ->> ''18'' as tc_18 -- ＥＣＵＭ時間
  ,treat_condition ->> ''19'' as tc_19 -- ＥＣＵＭ時間カウント選択
  ,treat_condition ->> ''20'' as tc_20 -- 除水目標値
  ,treat_condition ->> ''21'' as tc_21 -- 除水計算選択
  ,treat_condition ->> ''22'' as tc_22 -- 除水計算優先項目選択
  ,treat_condition ->> ''23'' as tc_23 -- シングルニードル電源ＳＷ
  ,treat_condition ->> ''24'' as tc_24 -- シングルニードル切替圧上限
  ,treat_condition ->> ''25'' as tc_25 -- シングルニードル切替圧下限
  ,treat_condition ->> ''26'' as tc_26 -- 透析液温度設定
  ,treat_condition ->> ''27'' as tc_27 -- 透析液流量設定値
  ,treat_condition ->> ''28'' as tc_28 -- 血流量設定
  ,treat_condition ->> ''29'' as tc_29 -- ＩＰ使用選択
  ,treat_condition ->> ''30'' as tc_30 -- ＩＰ速度設定0
  ,treat_condition ->> ''31'' as tc_31 -- ＩＰスタート
  ,treat_condition ->> ''32'' as tc_32 -- ＩＰ自動ワンショット
  ,treat_condition ->> ''33'' as tc_33 -- ＩＰワンショット量
  ,treat_condition ->> ''34'' as tc_34 -- ＩＰ電源報知切りＳＷ
  ,treat_condition ->> ''35'' as tc_35 -- ＩＰ電源報知切り時間
  ,treat_condition ->> ''36'' as tc_36 -- ＩＰ電源自動切りＳＷ
  ,treat_condition ->> ''37'' as tc_37 -- ＩＰ電源自動切り時間
  ,treat_condition ->> ''38'' as tc_38 -- クリップ式気泡検出器切りＳＷ
  ,treat_condition ->> ''39'' as tc_39 -- 除水開始遅延時間
  ,treat_condition ->> ''40'' as tc_40 -- 透析前体重
  ,treat_condition ->> ''41'' as tc_41 -- ＤＷ
  ,treat_condition ->> ''42'' as tc_42 -- 補正値の合計
  ,treat_condition ->> ''43'' as tc_43 -- 除水量制限
  ,treat_condition ->> ''44'' as tc_44 -- 除水量計算値
  ,treat_condition ->> ''45'' as tc_45 -- 除水補正項目名１
  ,treat_condition ->> ''53'' as tc_53 -- 除水補正値１
  ,treat_condition ->> ''54'' as tc_54 -- 除水補正項目名２
  ,treat_condition ->> ''62'' as tc_62 -- 除水補正値２
  ,treat_condition ->> ''63'' as tc_63 -- 除水補正項目名３
  ,treat_condition ->> ''71'' as tc_71 -- 除水補正値３
  ,treat_condition ->> ''72'' as tc_72 -- 除水補正項目名４
  ,treat_condition ->> ''80'' as tc_80 -- 除水補正値４
  ,treat_condition ->> ''81'' as tc_81 -- 除水補正項目名５
  ,treat_condition ->> ''89'' as tc_89 -- 除水補正値５
